// ========= المتغيرات العامة =========
let currentLat = 21.4225;
let currentLng = 39.8262;
// PLACE-NAMES-HOMEPAGE-DEFAULT-CITY-L10N-FIX-1 (2026-05-18):
// The hardcoded default-Mecca strings used to leak Arabic into non-AR
// homepages (e.g. /ur/ showed `مكة المكرمة` in #city-name + #qibla-city
// because the global `currentCity` started life as Arabic and the
// _initialSyncHydrate IIFE only runs for city routes with a slug —
// homepages match nothing in its regex and the default stands).
// Read the SSR-set `<html lang>` and pick the matching localized
// Mecca name from the same lang map as `curated_places.json`. Falls
// back to Arabic on any error.
let currentCity = (function () {
    // Values aligned with _LOCALIZED_CITY_MAPS (CITY_NAMES_*) defined later
    // in this file, so first-paint default matches what getDisplayCity()
    // would compute once init runs. For `id` + `ms` this means "Makkah"
    // (the form CITY_NAMES_ID + CITY_NAMES_MS use) rather than the
    // curated_places.json `Mekkah`/`Mekah` — avoids a brief flash on the
    // homepage default. Both forms are valid Indonesian/Malay; "Makkah"
    // matches the legacy site copy used elsewhere.
    var _MECCA_BY_LANG = {
        ar: 'مكة المكرمة', en: 'Mecca',   fr: 'La Mecque', de: 'Mekka',
        tr: 'Mekke',        ur: 'مکہ',    id: 'Makkah',    es: 'La Meca',
        bn: 'মক্কা',         ms: 'Makkah'
    };
    try {
        var _lang = (typeof document !== 'undefined' && document.documentElement)
            ? (document.documentElement.lang || 'ar') : 'ar';
        return _MECCA_BY_LANG[_lang] || _MECCA_BY_LANG.ar;
    } catch (_) { return _MECCA_BY_LANG.ar; }
})();
let currentEnglishName = 'Mecca'; // الاسم الإنجليزي للمدينة (للـ slug)
let currentEnglishDisplayName = 'Mecca'; // الاسم الإنجليزي مع الحي (للعرض)
let currentCountry = 'المملكة العربية السعودية';
let currentEnglishCountry = 'Saudi Arabia'; // الاسم الإنجليزي للدولة
let currentCountryCode = 'sa'; // كود ISO للدولة الحالية
// أسماء مترجمة إلى اللغة الحالية (ur/tr/fr) — تُعبَّأ من Nominatim بـ accept-language={lang}
// تبقى فارغة للعربية والإنجليزية لأنّ currentCity/currentEnglishName يغطيان الحالتَيْن
let currentLocalizedName = '';
let currentLocalizedCountry = '';

// ── MOON-SPA-ROUTER-MOON-PREFIX-ACTIVATION-AUDIT-1 (2026-06-17) ──────────────
//   Single source of truth for "is this pathname a MOON page?" — used by the SPA's
//   page-activation deciders (initApp activation block + the pageshow/BFCache
//   self-heal router). It matches BOTH the current stable flat routes AND any
//   /moon-prefixed nested path, with an optional /{lang}/ prefix:
//     • /moon            and  /moon/…   (e.g. /moon/{country}/{city}/today)  ← forward-ready
//     • /moon-today  ·  /moon-today-in-…  ·  /moon-in-…                       ← current routes
//   CLIENT-ONLY classifier: it ONLY decides which #page-* the SPA activates after
//   hydration. It adds NO server route, NO redirect, NO SSR — it just makes app.js
//   ready to show #page-moon if the server ever serves a /moon/… URL. A path is a
//   moon page iff it starts with "/moon" followed by "-today" | "-in-" | "/" | end;
//   "/moonshine", "/moonlight" etc. are deliberately NOT moon pages.
function _isMoonPath(p) {
    return /^\/(?:(?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon(?:-today|-in-|\/|$)/.test(String(p == null ? '' : p));
}
// MOON-CITY-YEAR-ROUTE-STRUCTURE-ADD-1: the city YEAR page /[lang/]moon/{country}/{city}/{yyyy}
//   is a SEPARATE SSR section (#page-moon-year), not the live #page-moon hub. This classifier
//   lets the SPA activate the right section + skip the hub updater on the year page.
function _isMoonYearPath(p) {
    return /^\/(?:(?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/[a-z][a-z0-9-]+\/\d{4}$/.test(String(p == null ? '' : p));
}
// MOON-CITY-MONTH-ROUTE-STRUCTURE-ADD-1: the city MONTH page /[lang/]moon/{country}/{city}/{yyyy}/{mm}
//   is its OWN SSR section (#page-moon-month). Activate that section + skip the hub updater on it.
function _isMoonMonthPath(p) {
    return /^\/(?:(?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/[a-z][a-z0-9-]+\/\d{4}\/\d{2}$/.test(String(p == null ? '' : p));
}
// MOON-CITY-DAY-…-SCOPE-CORRECTION-FIX-1: the nested DAY page /moon/{country}/{city}/{yyyy}/{mm}/{dd}
//   does NOT have its own section — it reuses the legacy dated renderer in #page-moon (normalized via
//   _moonPathname). So there is no _isMoonDayPath here; _isMoonPath classifies it as page-moon.

// UAT-FOUC: synchronous URL-slug → globals override at script-top.
//   Runs immediately when app.js executes (after `let` declarations, before
//   any other code or rendering). Reads the URL pathname for a city slug;
//   if found, looks up sessionStorage('city_${slug}') OR FAMOUS_MOON_CITIES
//   and overrides the Mecca defaults inline. This kills the "Mecca flash"
//   on cold visits to /qibla-in-X, /moon-today-in-X, /prayer-times-in-X.
//   Self-contained — does NOT depend on any function defined later
//   (no makeSlug, no _moonCityDisplayName), so it's safe to run pre-init.
(function _initialSyncHydrate() {
    try {
        const _p = (typeof window !== 'undefined' && window.location && window.location.pathname) || '';
        const _m = _p.match(/^\/(?:(?:en|fr|tr|ur|de|id|es|bn|ms)\/)?(?:qibla-in|prayer-times-in|moon-today-in|moon-in|time-left-until-next-prayer-in|next-prayer-in)-([a-z][a-z0-9.-]+?)(?:-(-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?))?(?:\/\d{4}-\d{2}-\d{2})?(?:\.html)?$/);
        // MOON-CITY-HUB-ROUTE-STRUCTURE-ADD-1: the nested city moon hub
        //   /[lang/]moon/{country}/{city} also carries a __PRAYER_CITY__ seed — match
        //   it (city in 2nd segment) so this pre-paint hydrator seeds the globals from
        //   the seed and skips the FOUC, same as the flat /moon-in-{city} routes.
        // MOON-CITY-HUB + YEAR-ROUTE-STRUCTURE-ADD-1: nested hub /moon/{country}/{city}
        //   AND the year page /moon/{country}/{city}/{yyyy} carry the city in the 2nd
        //   segment — seed globals from __PRAYER_CITY__ for both (no FOUC on either).
        // MOON-CITY-MONTH + DAY-ROUTE-STRUCTURE-ADD-1: the month /{yyyy}/{mm} and day
        //   /{yyyy}/{mm}/{dd} pages also carry the city in the 2nd segment — extend the
        //   optional tail so the pre-paint hydrator seeds globals on those too (no FOUC).
        // MOON-COUNTRY-CITY-LINKS-UPDATE-LOCATION-CONTEXT-1 (2026-06-25): include the
        //   nested-today route (/moon/{country}/{city}/today) in the optional tail.
        //   Without /today the pre-paint hydrator bailed on those pages (the tail only
        //   matched /{yyyy}[/mm[/dd]]), so currentCity was never seeded from
        //   __PRAYER_CITY__ and fell to a stale country-capital fallback (e.g. الرياض)
        //   — the sticky header (#city-name) then showed the wrong city after a city
        //   click from /moon/{country}.
        const _mNested = _p.match(/^\/(?:(?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/([a-z][a-z0-9-]+)(?:\/today|\/\d{4}(?:\/\d{2}(?:\/\d{2})?)?)?$/);
        if (!_m && !_mNested) return;
        const _slug = _m ? _m[1] : _mNested[1];
        const _urlLat = (_m && _m[2] != null) ? parseFloat(_m[2]) : NaN;
        const _urlLng = (_m && _m[3] != null) ? parseFloat(_m[3]) : NaN;
        // 0) PLACE-CITY-PAGE-L10N-FIX-1 (2026-05-14) — SSR-injected
        // `window.__PRAYER_CITY__` is the authoritative source on
        // /prayer-times-in-{slug} bare routes. Seed globals from it
        // BEFORE any sessionStorage / URL coord checks so first paint
        // already has the correct city + country (no FOUC, no Mecca
        // defaults flash, no English-on-Arabic fallback).
        try {
            if (window.__PRAYER_CITY__ && typeof window.__PRAYER_CITY__ === 'object') {
                const pc = window.__PRAYER_CITY__;
                if (isFinite(pc.lat) && isFinite(pc.lng) && pc.name && pc.country) {
                    currentLat = pc.lat;
                    currentLng = pc.lng;
                    currentCity = pc.name;
                    currentCountry = pc.country;
                    currentCountryCode = (pc.countryCode || '').toLowerCase();
                    currentEnglishName = pc.englishName || '';
                    currentEnglishDisplayName = pc.englishName || '';
                    // Synthesize the canonical English country name from
                    // the cc so getDisplayCountry()'s EN-lang branch has
                    // a value too. COUNTRY_EN_NAMES is initialized later
                    // in the file but defined as a module-level const,
                    // so it MAY not be evaluated yet — guard with typeof.
                    try {
                        if (currentCountryCode && typeof COUNTRY_EN_NAMES !== 'undefined') {
                            currentEnglishCountry = COUNTRY_EN_NAMES[currentCountryCode] || '';
                        }
                    } catch (_) {}
                    // MOON-COUNTRY-CITY-LINKS-UPDATE-LOCATION-CONTEXT-1 (2026-06-25): on a
                    //   nested moon city route the URL city is the source of truth. Adopt
                    //   it as the persistent nav context (selected_city + last_city_context
                    //   + city_moon) so the global nav tabs (prayer/qibla/moon, rewritten by
                    //   _applyLastCityNavLinks on init/pageshow) point at THIS city, never a
                    //   stale/foreign one (e.g. Paris/Riyadh). Same shape site-search.js
                    //   onPick writes. Scoped to nested-moon — flat prayer/qibla/moon-today-in
                    //   routes keep their existing selected_city behavior.
                    if (_mNested && pc.slug) {
                        try {
                            const _navCtx = JSON.stringify({
                                lat: pc.lat, lng: pc.lng, name: pc.name, country: pc.country,
                                englishName: pc.englishName || '',
                                countryCode: (pc.countryCode || '').toLowerCase(),
                                timezone: (pc.timezoneOffset != null ? pc.timezoneOffset : pc.timezone),
                                slug: pc.slug, ts: Date.now()
                            });
                            const _navSeed = JSON.stringify({
                                lat: pc.lat, lng: pc.lng, name: pc.name, country: pc.country,
                                englishName: pc.englishName || '',
                                countryCode: (pc.countryCode || '').toLowerCase(),
                                timezone: (pc.timezoneOffset != null ? pc.timezoneOffset : pc.timezone),
                                slug: pc.slug, _v: 2
                            });
                            sessionStorage.setItem('selected_city', _navCtx);
                            sessionStorage.setItem('last_city_context', _navCtx);
                            sessionStorage.setItem('city_moon', _navSeed);
                        } catch (_navErr) {}
                    }
                    return;
                }
            }
        } catch (_) {}
        // 1) sessionStorage seed (fastest, highest fidelity)
        try {
            const _stored = sessionStorage.getItem('city_' + _slug);
            if (_stored) {
                const _o = JSON.parse(_stored);
                if (_o && typeof _o.lat === 'number' && typeof _o.lng === 'number') {
                    currentLat = _o.lat; currentLng = _o.lng;
                    // BUG-FIX (country/city mismatch): when the seed exists for a
                    //   non-Mecca slug, NEVER let stale Saudi/Mecca defaults linger
                    //   for the country-name field. If the seed lacks country/
                    //   englishCountry, clear them — the reverse-geo step inside
                    //   loadCityData() will repopulate from the real coords. The
                    //   slug here is authoritative, so the previous-page country
                    //   (e.g. Saudi Arabia) MUST NOT bleed onto the Indian city.
                    const _seedSlugIsNotMecca = (_slug !== 'mecca' && _slug !== 'makkah');
                    currentCity = _o.name || (_seedSlugIsNotMecca ? '' : currentCity);
                    currentCountry = _o.country || (_seedSlugIsNotMecca ? '' : currentCountry);
                    currentCountryCode = _o.countryCode || (_seedSlugIsNotMecca ? '' : currentCountryCode);
                    currentEnglishCountry = _o.englishCountry || (_seedSlugIsNotMecca ? '' : currentEnglishCountry);
                    if (_o.englishName) {
                        currentEnglishName = _o.englishName;
                        currentEnglishDisplayName = _o.englishName;
                    } else if (_seedSlugIsNotMecca) {
                        currentEnglishName = '';
                        currentEnglishDisplayName = '';
                    }
                    return;
                }
            }
        } catch (_) {}
        // 2) URL coord-suffix
        if (isFinite(_urlLat) && isFinite(_urlLng)) {
            currentLat = _urlLat; currentLng = _urlLng;
            // Clear name defaults so first paint doesn't show "Mecca" — wait
            //   for _hydrateCurrentCityFromUrlOrStorage / loadXxxPage to fill in.
            currentCity = ''; currentEnglishName = ''; currentEnglishDisplayName = '';
            currentCountry = ''; currentEnglishCountry = ''; currentCountryCode = '';
            return;
        }
        // 3) loc-XX.X-YY.Y coord-only slug
        const _locM = _slug.match(/^loc-(\d+\.\d)([ns])-(\d+\.\d)([ew])$/);
        if (_locM) {
            currentLat = parseFloat(_locM[1]) * (_locM[2] === 'n' ? 1 : -1);
            currentLng = parseFloat(_locM[3]) * (_locM[4] === 'e' ? 1 : -1);
            currentCity = ''; currentEnglishName = ''; currentEnglishDisplayName = '';
            currentCountry = ''; currentEnglishCountry = ''; currentCountryCode = '';
            return;
        }
        // 4) URL has a name slug but no coords + no sessionStorage seed → clear
        //    the Mecca defaults to avoid a flash. Real coords come from
        //    FAMOUS_MOON_CITIES check inside _hydrateCurrentCityFromUrlOrStorage
        //    (fires on initApp).
        if (_slug !== 'mecca' && _slug !== 'makkah') {
            currentCity = ''; currentEnglishName = ''; currentEnglishDisplayName = '';
            currentCountry = ''; currentEnglishCountry = ''; currentCountryCode = '';
            currentLat = 0; currentLng = 0;
        }
    } catch (_) { /* fail-soft — keep Mecca defaults */ }
})();

// ============================================================
// ===== UAT-Moon-Today-Polish: arPluralDays — global helper ==
// Localized "N days" string respecting Arabic dual/plural categories.
// Exposed on window so it's reusable across moon, Ramadan, Eid,
// Hijri New Year countdowns, and prayer-times "X minutes/hours" labels.
//
// Categories per CLDR (and traditional Arabic grammar):
//   0      → "لا أيّام" (zero — uncommon but handled)
//   1      → "يومًا واحدًا" (singular)
//   2      → "يومين" (dual)
//   3-10   → "{n} أيّام" (few — sound plural)
//   11+    → "{n} يومًا" (many — singular accusative for tamyiz)
//
// Non-Arabic falls back to a complete localized phrase so the same
// helper drives all 10 languages without per-template branching.
// ============================================================
function arPluralDays(n, lang) {
    n = parseInt(n, 10);
    if (!isFinite(n) || n < 0) n = 0;
    switch ((lang || '').toLowerCase()) {
        case 'ar':
            if (n === 0) return 'لا أيام';
            if (n === 1) return 'يومًا واحدًا';
            if (n === 2) return 'يومين';
            if (n >= 3 && n <= 10) return n + ' أيام';
            return n + ' يومًا';
        case 'fr':
            return n + (n === 1 ? ' jour' : ' jours');
        case 'tr':
            return n + ' gün';
        case 'ur':
            return n + ' دن';
        case 'de':
            return n + (n === 1 ? ' Tag' : ' Tage');
        case 'id':
        case 'ms':
            return n + ' hari';
        case 'es':
            return n + (n === 1 ? ' día' : ' días');
        case 'bn':
            return n + ' দিন';
        case 'en':
        default:
            return n + (n === 1 ? ' day' : ' days');
    }
}
try { window.arPluralDays = arPluralDays; } catch (_) {}

