// MOON-CITY-HUB-ROUTE-STRUCTURE-ADD-1 (2026-06-18): the canonical city moon HUB now
//   lives at the nested /[lang/]moon/{country}/{city} (the legacy flat /moon-in-{city}
//   301s there). It renders the SAME content as the flat hub. Rather than thread the
//   new shape through every moon path parser, normalize it to the legacy flat form at
//   ONE chokepoint; the existing slug/coords/date/hub parsers then work unchanged.
//   (The breadcrumb builder intentionally does NOT use this — it detects the raw
//   nested path and leaves the SSR-rendered 4-level breadcrumb in place.)
function _moonPathname() {
    const p = window.location.pathname;
    // MOON-CITY-DAY-…-SCOPE-CORRECTION-FIX-1: the nested DAY /moon/{country}/{city}/{yyyy}/{mm}/{dd}
    //   renders the SAME content as the legacy /moon-in-{city}/{yyyy-mm-dd} — normalize it to the flat
    //   dated form here (the single chokepoint) so every date/slug parser works unchanged.
    const md = p.match(/^\/((?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/([a-z][a-z0-9-]+)\/(\d{4})\/(\d{2})\/(\d{2})$/);
    if (md) return '/' + (md[1] || '') + 'moon-in-' + md[2] + '/' + md[3] + '-' + md[4] + '-' + md[5];
    // MOON-CITY-TODAY-ROUTE-STRUCTURE-ADD-1: the nested TODAY /moon/{country}/{city}/today renders the
    //   SAME content as the legacy /moon-today-in-{city} — normalize it to the flat today form so every
    //   today parser (hero/forecast/coords) works unchanged.
    const mt = p.match(/^\/((?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/([a-z][a-z0-9-]+)\/today$/);
    if (mt) return '/' + (mt[1] || '') + 'moon-today-in-' + mt[2];
    // MOON-CITY-MONTH-…-SCOPE-CORRECTION-FIX-1: the nested MONTH /moon/{country}/{city}/{yyyy}/{mm}
    //   renders the SAME content as the legacy /moon-in-{city}/{yyyy-mm} — normalize it to the flat
    //   month form so the client month-calendar parser (updateMoonInfo) renders the URL month.
    const mmo = p.match(/^\/((?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/([a-z][a-z0-9-]+)\/(\d{4})\/(\d{2})$/);
    if (mmo) return '/' + (mmo[1] || '') + 'moon-in-' + mmo[2] + '/' + mmo[3] + '-' + mmo[4];
    const m = p.match(/^\/((?:en|fr|tr|ur|de|id|es|bn|ms)\/)?moon\/[a-z][a-z0-9-]+\/([a-z][a-z0-9-]+)$/);
    if (m) return '/' + (m[1] || '') + 'moon-in-' + m[2];
    return p;
}

function _moonCitySlugFromPath() {
    // Round 15 + Round 16 + UAT-Moon-Hub-Month: four URL shapes —
    //   /moon-today-in-{slug}[-{lat}-{lng}]                → صفحة اليوم
    //   /moon-in-{slug}[-{lat}-{lng}]/YYYY-MM-DD          → صفحة مؤرَّخة
    //   /moon-in-{slug}[-{lat}-{lng}]/YYYY-MM             → صفحة شهر (NEW)
    //   /moon-in-{slug}[-{lat}-{lng}]                      → صفحة hub (Round 16)
    // نُرجِع slug فقط — الإحداثيّات تُقرأ عبر _moonCoordsFromPath().
    // MOON-CITY-HUB-ROUTE-STRUCTURE-ADD-1: _moonPathname() maps the nested hub to the
    //   flat /moon-in-{city} form so the hub regex below resolves the city slug.
    const p = _moonPathname();
    let m = p.match(/\/moon-today-in-([a-z][a-z0-9-]+?)(?:-(-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?))?$/);
    if (m) return m[1];
    m = p.match(/\/moon-in-([a-z][a-z0-9-]+?)(?:-(-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?))?\/\d{4}-\d{2}-\d{2}$/);
    if (m) return m[1];
    // UAT-Moon-Hub-Month: month page /moon-in-{slug}/YYYY-MM
    m = p.match(/\/moon-in-([a-z][a-z0-9-]+?)(?:-(-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?))?\/\d{4}-\d{2}$/);
    if (m) return m[1];
    // Round 16: hub — /moon-in-{slug}[-{lat}-{lng}] بلا تاريخ
    m = p.match(/\/moon-in-([a-z][a-z0-9-]+?)(?:-(-?\d+(?:\.\d+)?)-(-?\d+(?:\.\d+)?))?$/);
    return m ? m[1] : null;
}

