// Repeat label — morning page uses the 10-lang dict (exact counts + generic "{n}" fallback);
// evening/prayer keep the Arabic forms.
function _azkarRepeatLabelAR(n) {
    n = Number(n) || 1;
    if (_azkarActivePageIsMorning()) {
        const ui = _azkarMorningUiMap();
        if (ui && ui.rep) {
            if (ui.rep[n] != null) return ui.rep[n];
            if (ui.repN) return String(ui.repN).replace('{n}', String(n));
        }
    } else if (_azkarActivePageIsEvening()) {
        // AZKAR-EVENING-PAGE-UI-LOCALIZATION-AND-QURAN-TRANSLATIONS-ALL-LANGUAGES-1: evening dict (shared rep map).
        const ui = _azkarEveningUiMap();
        if (ui && ui.rep) {
            if (ui.rep[n] != null) return ui.rep[n];
            if (ui.repN) return String(ui.repN).replace('{n}', String(n));
        }
    }
    if (n === 1) return 'مرة واحدة';
    if (n === 2) return 'مرتان';
    if (n === 3) return 'ثلاث مرات';
    if (n === 7) return 'سبع مرات';
    if (n === 10) return 'عشر مرات';
    if (n === 33) return 'ثلاث وثلاثون مرة';
    if (n === 100) return 'مئة مرة';
    if (n >= 3 && n <= 10) return n + ' مرات';
    return n + ' مرة';
}

