// ─────────────────────────────────────────────────────────────────────────────
// AZKAR-MORNING-SSR-RENDER-LIST-1 (2026-05-26): hydration-only path for
// SSR-rendered cards. Walks the existing DOM (built by server.js's
// _buildAzkarMorningListHtml), restores per-item localStorage counter
// state, and binds all interactive handlers. No DOM rebuild, no layout
// shift. Card structure MUST match what server.js produces — same ids,
// classes, attributes. If the schema diverges, fall back to the full
// re-render path (line ~23922 below) by removing data-ssr-rendered in
// server.js until both renderers are re-synchronized.
// ─────────────────────────────────────────────────────────────────────────────
function _hydrateAzkarMorningCards(items, listEl) {
    items.forEach((dhikr) => {
        const card = document.getElementById('azkar-item-' + dhikr.id);
        if (!card) return; // card missing from SSR — skip (will be picked up by JS re-render fallback elsewhere)

        const target = Number(dhikr.repeat) || 1;
        const isSingleRead = (target === 1);
        const restored = _azkarRestore(dhikr.category, dhikr.id);
        const isCompleted = restored >= target;

        // ── Apply completion class from localStorage ──
        if (isCompleted) card.classList.add('completed');
        else card.classList.remove('completed');

        if (isSingleRead) {
            // ── Variant A: mark-read button ──
            const tapBtn = card.querySelector('.azkar-mark-read');
            if (tapBtn) {
                tapBtn.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.markedRead
                    : _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', isCompleted ? 'true' : 'false');
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounter(dhikr, tapBtn, null, card);
                });
            }
        } else {
            // ── Variant B: counter pill + undo/reset controls ──
            const tapBtn = card.querySelector('.azkar-counter-tap');
            const tapCount = card.querySelector('.azkar-counter-tap-count');
            const tapPrompt = card.querySelector('.azkar-counter-tap-prompt');

            if (tapCount) tapCount.textContent = restored + ' / ' + target;
            if (tapPrompt) {
                tapPrompt.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.counterDone
                    : _AZKAR_AR_CHROME.counterTap;
            }
            if (tapBtn) {
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounter(dhikr, tapBtn, tapCount, card);
                });
            }

            const undoBtn = card.querySelector('.azkar-counter-undo');
            if (undoBtn) {
                undoBtn.addEventListener('click', () => {
                    const cur = _azkarRestore(dhikr.category, dhikr.id);
                    if (cur <= 0) return;
                    const next = cur - 1;
                    _azkarPersist(dhikr.category, dhikr.id, next, target);
                    if (tapCount) tapCount.textContent = next + ' / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updateMorningProgress();
                });
            }

            const resetItemBtn = card.querySelector('.azkar-counter-reset');
            if (resetItemBtn) {
                resetItemBtn.addEventListener('click', () => {
                    _azkarPersist(dhikr.category, dhikr.id, 0, target);
                    if (tapCount) tapCount.textContent = '0 / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updateMorningProgress();
                });
            }
        }
    });
}

// ─────────────────────────────────────────────────────────────────────────────
// AZKAR-EVENING-PHASE-1 (2026-05-26): evening category loader + hydrator.
// Clone of _loadAzkarMorning / _hydrateAzkarMorningCards adapted for:
//   - category id 'evening' (localStorage isolation)
//   - DOM ids: #azkar-evening-list, #azkar-evening-reset-all, #azkar-evening-completed
//   - Sticky wiring + events render reuse the morning helpers (no clone needed).
// Same SSR-hydration vs full-rebuild dispatch as morning.
// ─────────────────────────────────────────────────────────────────────────────
function _loadAzkarEvening() {
    const listEl = document.getElementById('azkar-evening-list');
    if (!listEl) return;
    if (listEl.dataset.wired) return;
    listEl.dataset.wired = '1';

    const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarEvening))
        ? window.AzkarEvening : [];

    // Reset-all button (page-level)
    const resetBtn = document.getElementById('azkar-evening-reset-all');
    if (resetBtn && !resetBtn.dataset.wired) {
        resetBtn.dataset.wired = '1';
        resetBtn.removeAttribute('data-i18n');
        resetBtn.addEventListener('click', () => {
            _azkarShowResetConfirm({
                title: 'هل تريد إعادة ضبط جميع العدادات؟',
                sub: 'سيتم تصفير تقدمك في هذا القسم والبدء من جديد.',
                cancelText: 'إلغاء',
                confirmText: 'نعم، إعادة الضبط',
                returnFocusTo: resetBtn,
                onConfirm: () => {
                    // AZKAR-RESET-COUNTERS-NO-RELOAD-FIX-1 (2026-05-26):
                    // reset in place — no DOM wipe, no re-call of
                    // _loadAzkarEvening (which would hit the SSR-fallback
                    // notice "تعذّر تحميل أذكار المساء" because
                    // data-ssr-rendered was just removed).
                    _azkarResetCategory('evening');
                    _azkarResetCardsInPlace('evening', items, _updateEveningProgress);
                    _azkarShowToast('تمت إعادة ضبط العدادات');
                    _azkarScrollToTopOfPage();
                }
            });
        });
    }

    // SSR HYDRATION PATH (preferred — matches AZKAR-MORNING-SSR-RENDER-LIST-1)
    if (listEl.dataset.ssrRendered === '1' && listEl.children.length > 0 && items.length) {
        _hydrateAzkarEveningCards(items, listEl);
        _updateEveningProgress();
        _azkarWireEveningStickyProgress();
        _azkarRenderMoonEvents();
        return;
    }

    // FALLBACK: SSR didn't inject cards (data load failure on server).
    // Show a small notice rather than re-implementing the full builder —
    // SSR injection is the supported path. If you see this in production,
    // check _AZKAR_EVENING_DATA loading in server.js startup logs.
    listEl.innerHTML = '';
    if (!items.length) {
        const empty = document.createElement('p');
        empty.className = 'azkar-empty';
        empty.textContent = _AZKAR_AR_CHROME.emptyList;
        listEl.appendChild(empty);
        _updateEveningProgress(0, 0);
        return;
    }
    // Non-SSR fallback rare path — log + show empty notice (user can
    // refresh; SSR will populate). Avoids duplicating the morning builder.
    try { console.warn('[azkar-evening] SSR cards missing — full client-render fallback not implemented (SSR is the supported path).'); } catch (_) {}
    const notice = document.createElement('p');
    notice.className = 'azkar-empty';
    notice.textContent = 'تعذر تحميل أذكار المساء. يرجى إعادة تحميل الصفحة.';
    listEl.appendChild(notice);
    _updateEveningProgress(0, items.length);
}

// Hydrator — same DOM walk as morning, but binds counter handlers to
// 'evening' category so localStorage stays isolated.
function _hydrateAzkarEveningCards(items, listEl) {
    items.forEach((dhikr) => {
        const card = document.getElementById('azkar-item-' + dhikr.id);
        if (!card) return;
        const target = Number(dhikr.repeat) || 1;
        const isSingleRead = (target === 1);
        const restored = _azkarRestore(dhikr.category, dhikr.id);
        const isCompleted = restored >= target;
        if (isCompleted) card.classList.add('completed');
        else card.classList.remove('completed');

        if (isSingleRead) {
            const tapBtn = card.querySelector('.azkar-mark-read');
            if (tapBtn) {
                tapBtn.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.markedRead
                    : _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', isCompleted ? 'true' : 'false');
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounterEvening(dhikr, tapBtn, null, card);
                });
            }
        } else {
            const tapBtn = card.querySelector('.azkar-counter-tap');
            const tapCount = card.querySelector('.azkar-counter-tap-count');
            const tapPrompt = card.querySelector('.azkar-counter-tap-prompt');
            if (tapCount) tapCount.textContent = restored + ' / ' + target;
            if (tapPrompt) {
                tapPrompt.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.counterDone
                    : _AZKAR_AR_CHROME.counterTap;
            }
            if (tapBtn) {
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounterEvening(dhikr, tapBtn, tapCount, card);
                });
            }
            const undoBtn = card.querySelector('.azkar-counter-undo');
            if (undoBtn) {
                undoBtn.addEventListener('click', () => {
                    const cur = _azkarRestore(dhikr.category, dhikr.id);
                    if (cur <= 0) return;
                    const next = cur - 1;
                    _azkarPersist(dhikr.category, dhikr.id, next, target);
                    if (tapCount) tapCount.textContent = next + ' / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updateEveningProgress();
                });
            }
            const resetItemBtn = card.querySelector('.azkar-counter-reset');
            if (resetItemBtn) {
                resetItemBtn.addEventListener('click', () => {
                    _azkarPersist(dhikr.category, dhikr.id, 0, target);
                    if (tapCount) tapCount.textContent = '0 / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updateEveningProgress();
                });
            }
        }
    });
}

// Evening-scoped tick (calls _azkarAdvanceToNext like morning).
function _azkarTickCounterEvening(dhikr, tapBtn, tapCount, card) {
    const target = Number(dhikr.repeat) || 1;
    const isSingleRead = (target === 1);
    const cur = _azkarRestore(dhikr.category, dhikr.id);

    if (isSingleRead) {
        const next = (cur >= 1) ? 0 : 1;
        _azkarPersist(dhikr.category, dhikr.id, next, target);
        if (next === 1) {
            card.classList.add('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markedRead;
                tapBtn.setAttribute('aria-pressed', 'true');
            }
            _updateEveningProgress();
            _azkarAdvanceToNext(card);
        } else {
            card.classList.remove('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', 'false');
            }
            _updateEveningProgress();
        }
        return;
    }

    if (cur >= target) return;
    const next = cur + 1;
    _azkarPersist(dhikr.category, dhikr.id, next, target);
    if (tapCount) tapCount.textContent = next + ' / ' + target;
    if (next >= target) {
        card.classList.add('completed');
        const promptEl = tapBtn && tapBtn.querySelector
            ? tapBtn.querySelector('.azkar-counter-tap-prompt')
            : null;
        if (promptEl) promptEl.textContent = _AZKAR_AR_CHROME.counterDone;
        _updateEveningProgress();
        _azkarAdvanceToNext(card);
    }
}

// Progress update for evening (mirror of _updateMorningProgress).
function _updateEveningProgress(_doneOverride, _totalOverride) {
    const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarEvening))
        ? window.AzkarEvening : [];
    const total = (typeof _totalOverride === 'number') ? _totalOverride : items.length;
    let done = (typeof _doneOverride === 'number') ? _doneOverride : 0;
    if (typeof _doneOverride !== 'number') {
        items.forEach((d) => {
            const c = _azkarRestore(d.category, d.id);
            const t = Number(d.repeat) || 1;
            if (c >= t) done++;
        });
    }
    const pct = total > 0 ? Math.round((done / total) * 100) : 0;
    // AZKAR-EVENING-PAGE-UI-LOCALIZATION-AND-QURAN-TRANSLATIONS-ALL-LANGUAGES-1: localize the live progress
    // label via the active-page-aware chrome Proxy (evening dict on the evening page; the Arabic base's
    // progressTpl is byte-identical to the old hardcoded string, so /ar is unchanged). Mirrors morning.
    const labelText = _AZKAR_AR_CHROME.progressTpl(done, total);
    const labelEl = document.getElementById('azkar-evening-progress-label');
    if (labelEl) labelEl.textContent = labelText;
    const stickyLabel = document.getElementById('azkar-evening-sticky-label');
    if (stickyLabel) stickyLabel.textContent = labelText;
    const fillEl = document.getElementById('azkar-evening-progress-fill');
    if (fillEl) fillEl.style.width = pct + '%';
    const stickyFill = document.getElementById('azkar-evening-sticky-fill');
    if (stickyFill) stickyFill.style.width = pct + '%';
    const progressBars = document.querySelectorAll(
        '#azkar-evening-progress-wrap [role="progressbar"], #azkar-evening-sticky [role="progressbar"]'
    );
    progressBars.forEach(pb => pb.setAttribute('aria-valuenow', String(pct)));
    const banner = document.getElementById('azkar-evening-completed');
    if (banner) {
        if (total > 0 && done >= total) banner.classList.remove('u-hidden');
        else banner.classList.add('u-hidden');
    }
}

// Sticky-progress wiring for evening (mirror of _azkarWireStickyProgress).
function _azkarWireEveningStickyProgress() {
    try {
        const sticky = document.getElementById('azkar-evening-sticky');
        const progressWrap = document.getElementById('azkar-evening-progress-wrap');
        if (!sticky || !progressWrap) return;

        if (!sticky.dataset.io && typeof IntersectionObserver === 'function') {
            sticky.dataset.io = '1';
            const io = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) sticky.classList.remove('azkar-sticky-progress--visible');
                    else sticky.classList.add('azkar-sticky-progress--visible');
                });
            }, { rootMargin: '0px 0px 0px 0px', threshold: 0 });
            io.observe(progressWrap);
        }

        const stickyReset = document.getElementById('azkar-evening-sticky-reset');
        if (stickyReset && !stickyReset.dataset.wired) {
            stickyReset.dataset.wired = '1';
            const listEl = document.getElementById('azkar-evening-list');
            stickyReset.addEventListener('click', function () {
                _azkarShowResetConfirm({
                    title: 'هل تريد إعادة ضبط جميع العدادات؟',
                    sub: 'سيتم تصفير تقدمك في هذا القسم والبدء من جديد.',
                    cancelText: 'إلغاء',
                    confirmText: 'نعم، إعادة الضبط',
                    returnFocusTo: stickyReset,
                    onConfirm: function () {
                        // AZKAR-RESET-COUNTERS-NO-RELOAD-FIX-1 (2026-05-26).
                        _azkarResetCategory('evening');
                        const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarEvening))
                            ? window.AzkarEvening : [];
                        _azkarResetCardsInPlace('evening', items, _updateEveningProgress);
                        _azkarShowToast('تمت إعادة ضبط العدادات');
                        _azkarScrollToTopOfPage();
                    }
                });
            });
        }
    } catch (_) { /* never throw — sticky bar is best-effort UX */ }
}

// ─────────────────────────────────────────────────────────────────────────────
// AZKAR-PRAYER-PHASE-1 (2026-05-26): prayer category — clone of evening
// adapted for 17 prayer-position dhikr. category='prayer', storage key
// 'azkar.progress.prayer'. DOM ids prefixed with 'azkar-prayer-'.
// ─────────────────────────────────────────────────────────────────────────────
function _loadAzkarPrayer() {
    const listEl = document.getElementById('azkar-prayer-list');
    if (!listEl) return;
    if (listEl.dataset.wired) return;
    listEl.dataset.wired = '1';

    const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarPrayer))
        ? window.AzkarPrayer : [];

    const resetBtn = document.getElementById('azkar-prayer-reset-all');
    if (resetBtn && !resetBtn.dataset.wired) {
        resetBtn.dataset.wired = '1';
        resetBtn.removeAttribute('data-i18n');
        resetBtn.addEventListener('click', () => {
            _azkarShowResetConfirm({
                title: 'هل تريد إعادة ضبط جميع العدادات؟',
                sub: 'سيتم تصفير تقدمك في هذا القسم والبدء من جديد.',
                cancelText: 'إلغاء',
                confirmText: 'نعم، إعادة الضبط',
                returnFocusTo: resetBtn,
                onConfirm: () => {
                    // AZKAR-RESET-COUNTERS-NO-RELOAD-FIX-1 (2026-05-26):
                    // reset in place — no DOM wipe, no re-call of
                    // _loadAzkarPrayer (which would hit the SSR-fallback
                    // notice "تعذّر تحميل أذكار الصلاة" because
                    // data-ssr-rendered was just removed).
                    _azkarResetCategory('prayer');
                    _azkarResetCardsInPlace('prayer', items, _updatePrayerProgress);
                    _azkarShowToast('تمت إعادة ضبط العدادات');
                    _azkarScrollToTopOfPage();
                }
            });
        });
    }

    if (listEl.dataset.ssrRendered === '1' && listEl.children.length > 0 && items.length) {
        _hydrateAzkarPrayerCards(items, listEl);
        _updatePrayerProgress();
        _azkarWirePrayerStickyProgress();
        _azkarRenderMoonEvents();
        return;
    }

    listEl.innerHTML = '';
    if (!items.length) {
        const empty = document.createElement('p');
        empty.className = 'azkar-empty';
        empty.textContent = _AZKAR_AR_CHROME.emptyList;
        listEl.appendChild(empty);
        _updatePrayerProgress(0, 0);
        return;
    }
    try { console.warn('[azkar-prayer] SSR cards missing — full client-render fallback not implemented (SSR is the supported path).'); } catch (_) {}
    const notice = document.createElement('p');
    notice.className = 'azkar-empty';
    notice.textContent = 'تعذر تحميل أذكار الصلاة. يرجى إعادة تحميل الصفحة.';
    listEl.appendChild(notice);
    _updatePrayerProgress(0, items.length);
}

function _hydrateAzkarPrayerCards(items, listEl) {
    items.forEach((dhikr) => {
        const card = document.getElementById('azkar-item-' + dhikr.id);
        if (!card) return;
        const target = Number(dhikr.repeat) || 1;
        const isSingleRead = (target === 1);
        const restored = _azkarRestore(dhikr.category, dhikr.id);
        const isCompleted = restored >= target;
        if (isCompleted) card.classList.add('completed');
        else card.classList.remove('completed');

        if (isSingleRead) {
            const tapBtn = card.querySelector('.azkar-mark-read');
            if (tapBtn) {
                tapBtn.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.markedRead
                    : _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', isCompleted ? 'true' : 'false');
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounterPrayer(dhikr, tapBtn, null, card);
                });
            }
        } else {
            const tapBtn = card.querySelector('.azkar-counter-tap');
            const tapCount = card.querySelector('.azkar-counter-tap-count');
            const tapPrompt = card.querySelector('.azkar-counter-tap-prompt');
            if (tapCount) tapCount.textContent = restored + ' / ' + target;
            if (tapPrompt) {
                tapPrompt.textContent = isCompleted
                    ? _AZKAR_AR_CHROME.counterDone
                    : _AZKAR_AR_CHROME.counterTap;
            }
            if (tapBtn) {
                tapBtn.addEventListener('click', () => {
                    _azkarTickCounterPrayer(dhikr, tapBtn, tapCount, card);
                });
            }
            const undoBtn = card.querySelector('.azkar-counter-undo');
            if (undoBtn) {
                undoBtn.addEventListener('click', () => {
                    const cur = _azkarRestore(dhikr.category, dhikr.id);
                    if (cur <= 0) return;
                    const next = cur - 1;
                    _azkarPersist(dhikr.category, dhikr.id, next, target);
                    if (tapCount) tapCount.textContent = next + ' / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updatePrayerProgress();
                });
            }
            const resetItemBtn = card.querySelector('.azkar-counter-reset');
            if (resetItemBtn) {
                resetItemBtn.addEventListener('click', () => {
                    _azkarPersist(dhikr.category, dhikr.id, 0, target);
                    if (tapCount) tapCount.textContent = '0 / ' + target;
                    card.classList.remove('completed');
                    if (tapPrompt) tapPrompt.textContent = _AZKAR_AR_CHROME.counterTap;
                    _updatePrayerProgress();
                });
            }
        }
    });
}

function _azkarTickCounterPrayer(dhikr, tapBtn, tapCount, card) {
    const target = Number(dhikr.repeat) || 1;
    const isSingleRead = (target === 1);
    const cur = _azkarRestore(dhikr.category, dhikr.id);
    if (isSingleRead) {
        const next = (cur >= 1) ? 0 : 1;
        _azkarPersist(dhikr.category, dhikr.id, next, target);
        if (next === 1) {
            card.classList.add('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markedRead;
                tapBtn.setAttribute('aria-pressed', 'true');
            }
            _updatePrayerProgress();
            _azkarAdvanceToNext(card);
        } else {
            card.classList.remove('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', 'false');
            }
            _updatePrayerProgress();
        }
        return;
    }
    if (cur >= target) return;
    const next = cur + 1;
    _azkarPersist(dhikr.category, dhikr.id, next, target);
    if (tapCount) tapCount.textContent = next + ' / ' + target;
    if (next >= target) {
        card.classList.add('completed');
        const promptEl = tapBtn && tapBtn.querySelector
            ? tapBtn.querySelector('.azkar-counter-tap-prompt')
            : null;
        if (promptEl) promptEl.textContent = _AZKAR_AR_CHROME.counterDone;
        _updatePrayerProgress();
        _azkarAdvanceToNext(card);
    }
}

function _updatePrayerProgress(_doneOverride, _totalOverride) {
    const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarPrayer))
        ? window.AzkarPrayer : [];
    const total = (typeof _totalOverride === 'number') ? _totalOverride : items.length;
    let done = (typeof _doneOverride === 'number') ? _doneOverride : 0;
    if (typeof _doneOverride !== 'number') {
        items.forEach((d) => {
            const c = _azkarRestore(d.category, d.id);
            const t = Number(d.repeat) || 1;
            if (c >= t) done++;
        });
    }
    const pct = total > 0 ? Math.round((done / total) * 100) : 0;
    const labelText = 'تم إكمال ' + done + ' من ' + total;
    const labelEl = document.getElementById('azkar-prayer-progress-label');
    if (labelEl) labelEl.textContent = labelText;
    const stickyLabel = document.getElementById('azkar-prayer-sticky-label');
    if (stickyLabel) stickyLabel.textContent = labelText;
    const fillEl = document.getElementById('azkar-prayer-progress-fill');
    if (fillEl) fillEl.style.width = pct + '%';
    const stickyFill = document.getElementById('azkar-prayer-sticky-fill');
    if (stickyFill) stickyFill.style.width = pct + '%';
    const progressBars = document.querySelectorAll(
        '#azkar-prayer-progress-wrap [role="progressbar"], #azkar-prayer-sticky [role="progressbar"]'
    );
    progressBars.forEach(pb => pb.setAttribute('aria-valuenow', String(pct)));
    const banner = document.getElementById('azkar-prayer-completed');
    if (banner) {
        if (total > 0 && done >= total) banner.classList.remove('u-hidden');
        else banner.classList.add('u-hidden');
    }
}

function _azkarWirePrayerStickyProgress() {
    try {
        const sticky = document.getElementById('azkar-prayer-sticky');
        const progressWrap = document.getElementById('azkar-prayer-progress-wrap');
        if (!sticky || !progressWrap) return;
        if (!sticky.dataset.io && typeof IntersectionObserver === 'function') {
            sticky.dataset.io = '1';
            const io = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) sticky.classList.remove('azkar-sticky-progress--visible');
                    else sticky.classList.add('azkar-sticky-progress--visible');
                });
            }, { rootMargin: '0px 0px 0px 0px', threshold: 0 });
            io.observe(progressWrap);
        }
        const stickyReset = document.getElementById('azkar-prayer-sticky-reset');
        if (stickyReset && !stickyReset.dataset.wired) {
            stickyReset.dataset.wired = '1';
            const listEl = document.getElementById('azkar-prayer-list');
            stickyReset.addEventListener('click', function () {
                _azkarShowResetConfirm({
                    title: 'هل تريد إعادة ضبط جميع العدادات؟',
                    sub: 'سيتم تصفير تقدمك في هذا القسم والبدء من جديد.',
                    cancelText: 'إلغاء',
                    confirmText: 'نعم، إعادة الضبط',
                    returnFocusTo: stickyReset,
                    onConfirm: function () {
                        // AZKAR-RESET-COUNTERS-NO-RELOAD-FIX-1 (2026-05-26).
                        _azkarResetCategory('prayer');
                        const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarPrayer))
                            ? window.AzkarPrayer : [];
                        _azkarResetCardsInPlace('prayer', items, _updatePrayerProgress);
                        _azkarShowToast('تمت إعادة ضبط العدادات');
                        _azkarScrollToTopOfPage();
                    }
                });
            });
        }
    } catch (_) { /* never throw */ }
}

function _azkarTickCounter(dhikr, tapBtn, tapCount, card) {
    const target = Number(dhikr.repeat) || 1;
    const isSingleRead = (target === 1);
    const cur = _azkarRestore(dhikr.category, dhikr.id);

    if (isSingleRead) {
        // Toggle: 0 → 1 (mark read), 1 → 0 (unmark)
        const next = (cur >= 1) ? 0 : 1;
        _azkarPersist(dhikr.category, dhikr.id, next, target);
        if (next === 1) {
            card.classList.add('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markedRead;
                tapBtn.setAttribute('aria-pressed', 'true');
            }
            _updateMorningProgress();
            // AZKAR-AUTO-ADVANCE-1: only when transitioning 0 → 1 (mark-read,
            // not un-mark) — interactive completion, not a restore.
            _azkarAdvanceToNext(card);
        } else {
            card.classList.remove('completed');
            if (tapBtn) {
                tapBtn.textContent = _AZKAR_AR_CHROME.markRead;
                tapBtn.setAttribute('aria-pressed', 'false');
            }
            _updateMorningProgress();
            // NO scroll on un-mark
        }
        return;
    }

    // Multi-count tap: cap at target
    if (cur >= target) return;
    const next = cur + 1;
    _azkarPersist(dhikr.category, dhikr.id, next, target);
    if (tapCount) tapCount.textContent = next + ' / ' + target;
    if (next >= target) {
        card.classList.add('completed');
        // Flip the prompt text on the counter pill itself
        const promptEl = tapBtn && tapBtn.querySelector
            ? tapBtn.querySelector('.azkar-counter-tap-prompt')
            : null;
        if (promptEl) promptEl.textContent = _AZKAR_AR_CHROME.counterDone;
        _updateMorningProgress();
        // AZKAR-AUTO-ADVANCE-1: only when the counter *just* crossed
        // target on this user click — not on intermediate ticks, not on
        // restore-from-localStorage.
        _azkarAdvanceToNext(card);
    } else {
        _updateMorningProgress();
        // NO scroll on intermediate counts (1/3, 2/3, …)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// AZKAR-AUTO-ADVANCE-1 (2026-05-25)
// Smoothly scroll to the next dhikr card when the current one is completed
// by an interactive tap. Respects prefers-reduced-motion. Never triggered
// during page-load restore, undo, or reset. If the current card is the
// LAST card in the list, scroll to the completion banner instead.
//
// AZKAR-MOBILE-STICKY-OFFSET-2 (2026-05-25): replaces raw scrollIntoView
// with `_azkarScrollToCard()` that compensates for the sticky-progress
// bar height per-breakpoint (200/190/130 px). Native scrollIntoView
// ignores sticky overlays so the next card's title (and sometimes the
// first line of Quran text) was hidden behind the sticky bar on mobile.
// ─────────────────────────────────────────────────────────────────────────────

// ── AZKAR scroll helpers (shared by auto-advance + reset-to-top) ─────────────
function _azkarPrefersReducedMotion() {
    try {
        return (typeof window.matchMedia === 'function')
            && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    } catch (_) { return false; }
}
function _azkarOffsetPx() {
    // Per-breakpoint pixel budget that clears the sticky-progress bar.
    // 480-: 200px (mobile), 768-: 190px (tablet), else 130px (desktop).
    const w = (typeof window !== 'undefined' && window.innerWidth) || 1024;
    if (w <= 480) return 200;
    if (w <= 768) return 190;
    return 130;
}
function _azkarScrollToCard(card) {
    if (!card) return;
    try {
        const offset = _azkarOffsetPx();
        const top = card.getBoundingClientRect().top + window.scrollY;
        const target = Math.max(top - offset, 0);
        window.scrollTo({
            top: target,
            behavior: _azkarPrefersReducedMotion() ? 'auto' : 'smooth'
        });
    } catch (_) {
        try { card.scrollIntoView({ behavior: 'auto', block: 'start' }); } catch (_e) {}
    }
}
function _azkarScrollToTopOfPage() {
    // AZKAR-RESET-SCROLL-TO-TOP-2 (2026-05-25) + AZKAR-EVENING-PHASE-1 (2026-05-26):
    // Scope the lookup to the ACTIVE page wrapper so morning/evening don't
    // step on each other. Targets, in order:
    //   1. .azkar-page-top (class — evening uses unique id #azkar-page-top-evening)
    //   2. #azkar-page-top (legacy id — morning only)
    //   3. .azkar-hero (the hero card)
    //   4. the active page root (#page-azkar-morning / #page-azkar-evening)
    // Falls back to window.scrollTo({top:0}) if all targets fail.
    try {
        const activePage = document.querySelector('.page.active');
        const within = activePage || document;
        const target = within.querySelector('.azkar-page-top')
            || within.querySelector('#azkar-page-top')
            || within.querySelector('.azkar-hero')
            || activePage;
        if (!target) {
            window.scrollTo({ top: 0, behavior: _azkarPrefersReducedMotion() ? 'auto' : 'smooth' });
            return;
        }
        const offset = _azkarOffsetPx();
        const top = target.getBoundingClientRect().top + window.scrollY;
        const targetY = Math.max(top - offset, 0);
        window.scrollTo({
            top: targetY,
            behavior: _azkarPrefersReducedMotion() ? 'auto' : 'smooth'
        });
    } catch (_) {
        try { window.scrollTo(0, 0); } catch (_e) {}
    }
}

function _azkarAdvanceToNext(currentCardEl) {
    if (!currentCardEl) return;
    try {
        const prefersReducedMotion = _azkarPrefersReducedMotion();
        const behavior = prefersReducedMotion ? 'auto' : 'smooth';

        // Find the next sibling that is an azkar card
        let nextCard = currentCardEl.nextElementSibling;
        while (nextCard && !nextCard.classList.contains('azkar-card-item')) {
            nextCard = nextCard.nextElementSibling;
        }

        // Small perceptual delay so the user sees the completion state
        // flip on the current card before the page starts to move.
        const startDelay = prefersReducedMotion ? 0 : 240;

        if (nextCard) {
            setTimeout(() => {
                // AZKAR-MOBILE-STICKY-OFFSET-2: offset-aware scroll (was
                // scrollIntoView which ignored the sticky bar on mobile).
                _azkarScrollToCard(nextCard);
                // Subtle highlight on arrival (CSS animation handles fade-out
                // and is auto-disabled under prefers-reduced-motion)
                nextCard.classList.remove('azkar-just-arrived');
                // force reflow so re-adding the class restarts the animation
                void nextCard.offsetWidth;
                nextCard.classList.add('azkar-just-arrived');
                setTimeout(() => {
                    if (nextCard) nextCard.classList.remove('azkar-just-arrived');
                }, 1600);
            }, startDelay);
            return;
        }

        // No next card → this was the LAST dhikr. Show completion banner +
        // scroll into view (banner visibility is also driven by
        // _updateMorningProgress, but we reveal it here as a defensive net).
        const banner = document.getElementById('azkar-morning-completed');
        if (banner) {
            setTimeout(() => {
                banner.classList.remove('u-hidden');
                try { banner.scrollIntoView({ behavior: behavior, block: 'start' }); } catch (_) {
                    banner.scrollIntoView();
                }
            }, startDelay);
        }
    } catch (_) { /* silent — auto-advance is a UX nicety, never throw */ }
}

function _updateMorningProgress(_doneOverride, _totalOverride) {
    const items = (typeof window !== 'undefined' && Array.isArray(window.AzkarMorning))
        ? window.AzkarMorning : [];
    const total = (typeof _totalOverride === 'number') ? _totalOverride : items.length;
    let done = 0;
    if (typeof _doneOverride === 'number') {
        done = _doneOverride;
    } else {
        for (const d of items) {
            const c = _azkarRestore(d.category, d.id);
            if (c >= (Number(d.repeat) || 1)) done++;
        }
    }
    const lblEl = document.getElementById('azkar-morning-progress-label');
    const fillEl = document.getElementById('azkar-morning-progress-fill');
    const completedBanner = document.getElementById('azkar-morning-completed');
    const pct = total > 0 ? Math.round((done / total) * 100) : 0;

    if (lblEl) {
        // Hardcoded Arabic — never call t() here (prevents raw-key leak).
        lblEl.removeAttribute('data-i18n');
        lblEl.removeAttribute('data-i18n-template');
        lblEl.textContent = _AZKAR_AR_CHROME.progressTpl(done, total);
    }
    if (fillEl) {
        fillEl.style.width = pct + '%';
        const bar = fillEl.parentElement;
        if (bar && bar.setAttribute) bar.setAttribute('aria-valuenow', String(pct));
    }
    // STICKY-PROGRESS-1: keep the sticky compact bar in sync with the
    // inline one. Sticky elements may not exist on first render — guarded.
    const stickyLbl = document.getElementById('azkar-morning-sticky-label');
    const stickyFill = document.getElementById('azkar-morning-sticky-fill');
    if (stickyLbl) stickyLbl.textContent = _AZKAR_AR_CHROME.progressTpl(done, total);
    if (stickyFill) {
        stickyFill.style.width = pct + '%';
        const sBar = stickyFill.parentElement;
        if (sBar && sBar.setAttribute) sBar.setAttribute('aria-valuenow', String(pct));
    }
    if (completedBanner) {
        if (total > 0 && done >= total) {
            completedBanner.classList.remove('u-hidden');
        } else {
            completedBanner.classList.add('u-hidden');
        }
    }
}

// =============================================================================
// HOME-SEARCH-APPLY-SEARCH-TEST-COMPONENT-1 (extended 2026-05-25)
// =============================================================================
// Applies the /search-test (db/places/search-test.html) approved
// implementation to FOUR search components:
//   1. #loc-hero-search → homepage `/` AND /prayer-times-in-{city}
//      (both use the same hero input). Navigate to /prayer-times-in-{slug}.
//   2. #moon-hub-search → /moon-today (hub) + /moon-today-in-{slug}.
//      Navigate to /moon-today-in-{slug}.
//   3. #qibla-hub-search → /qibla (hub). Navigate to /qibla-in-{slug}.
//
// All four use the SAME backend (/api/search-place direct, no LOCAL_CITIES,
// no v1 Nominatim cascade), SAME 150ms debounce, SAME result filter
// (isPrayerTimesReady), SAME markup (<button class="search-test-result">
// with TYPE · COUNTRY subtitle order + 2× retina flag srcset), SAME
// keyboard handling (Enter picks first, Escape closes). Only the
// target route differs per page.
//
// Lang-prefix preserved: if the user is on /ur/qibla they navigate to
// /ur/qibla-in-{slug}, not /qibla-in-{slug}.
//
// The override happens via two routes:
//   A. window.onHeroSearchInput / window.onHeroSearchKeyDown — reassigned
//      so the inline HTML handlers (oninput="onHeroSearchInput(this.value)")
//      route through us.
//   B. window.onCitySearchInput / window.onSearchKeyDown — reassigned so
//      the moon/qibla legacy listeners (which do
//      `addEventListener('input', () => onCitySearchInput(value, MOON_CTX))`)
//      end up calling us too. The override checks ctx.targetRoute and
//      routes to the matching pipeline. Non-moon/qibla calls fall back
//      to the original onCitySearchInput so any other consumers keep
//      working.
//
// /search-test page itself (db/places/search-test.html) is byte-identical
// — its own self-contained JS continues to run untouched.
// =============================================================================
(function _wireSearchTestPipelineEverywhere() {
    'use strict';
    if (typeof window === 'undefined') return;

    const _SUPPORTED_LANGS = ['ar','en','fr','de','tr','ur','id','es','bn','ms'];

    const _STESC = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => (
        { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]
    ));

    function _stPickLang() {
        try {
            const params = new URLSearchParams(window.location.search);
            const fromQs = String(params.get('lang') || '').toLowerCase();
            if (fromQs && _SUPPORTED_LANGS.includes(fromQs)) return fromQs;
            const fromHtml = String(document.documentElement.lang || 'ar').toLowerCase();
            return _SUPPORTED_LANGS.includes(fromHtml) ? fromHtml : 'ar';
        } catch (_) { return 'ar'; }
    }

    function _stCurrentLangPrefix() {
        try {
            const p = (window.location && window.location.pathname) || '';
            const m = p.match(/^\/(en|fr|tr|ur|de|id|es|bn|ms)(?=\/|$)/);
            return m ? '/' + m[1] : '';
        } catch (_) { return ''; }
    }

    // COUNTRY-PRAYER-PAGE-SEARCH-PIPELINE-PARITY-FIX-1: core now lives in
    // js/site-search.js (window.SiteSearch) — single source of truth shared with
    // the country page. This thin wrapper keeps the existing wiring intact.
    // (SITE-SEARCH-LEGACY-UNUSED-CLEANUP-1: removed the now-orphaned route-builder wrapper —
    // its only caller was the deleted legacy pick handler; live routing goes through SiteSearch.)
    function _stIsPrayerTimesReady(r) { return window.SiteSearch.isReady(r); }

    // Per-suggestions-container state (lastResults + debounce + targetRoute).
    // Keyed by suggestionsId so each box has independent state.
    const _STATES = {};
    function _stStateFor(suggestionsId, targetRoute) {
        let s = _STATES[suggestionsId];
        if (!s) {
            s = _STATES[suggestionsId] = {
                suggestionsId: suggestionsId,
                targetRoute: targetRoute,
                lastResults: [],
                debounce: null
            };
        }
        // targetRoute can change if the same container is reused (unlikely
        // but safe). Always pin the latest value the caller wants.
        if (targetRoute) s.targetRoute = targetRoute;
        return s;
    }

    function _stHide(state) {
        const box = document.getElementById(state.suggestionsId);
        if (!box) return;
        box.hidden = true;
        box.classList.remove('open');
        box.innerHTML = '';
    }
    function _stShowLoading(state, IS_AR) {
        const box = document.getElementById(state.suggestionsId);
        if (!box) return;
        box.innerHTML = '<div class="search-test-loading">' +
            _STESC(IS_AR ? 'جاري البحث...' : 'Searching...') + '</div>';
        box.hidden = false;
        box.classList.add('open');
    }
    function _stShowEmptyWithStatus(state, status, IS_AR) {
        const box = document.getElementById(state.suggestionsId);
        if (!box) return;
        const externalDown = (status === 'rate_limited' || status === 'error' || status === 'timeout');
        const msg = externalDown
            ? (IS_AR
                ? 'تعذر البحث الخارجي مؤقتاً. جرب مرة أخرى بعد قليل، أو ابحث باسم مدينة أكبر قريبة.'
                : 'External place search is temporarily unavailable. Please try again shortly.')
            : (IS_AR ? 'لا توجد نتائج' : 'No results');
        box.innerHTML = '<div class="search-test-empty"' +
            (externalDown ? ' data-status="' + _STESC(status) + '"' : '') + '>' +
            _STESC(msg) + '</div>';
        box.hidden = false;
        box.classList.add('open');
    }
    // COUNTRY-PRAYER-PAGE-SEARCH-PIPELINE-PARITY-FIX-1: pick (persist + seed +
    // navigate) is the shared window.SiteSearch.onPick — identical logic, single
    // source of truth. (SITE-SEARCH-LEGACY-UNUSED-CLEANUP-1: removed the retained,
    // never-called legacy provenance copy of this handler — confirmed dead code.)
    function _stOnPick(state, r, LANG) {
        return window.SiteSearch.onPick(r, { targetRoute: state.targetRoute, lang: LANG });
    }
    function _stRenderResults(state, results, status, LANG, IS_AR) {
        const box = document.getElementById(state.suggestionsId);
        if (!box) return;
        state.lastResults = Array.isArray(results) ? results.filter(_stIsPrayerTimesReady) : [];
        if (!state.lastResults.length) { _stShowEmptyWithStatus(state, status || 'empty', IS_AR); return; }
        // Shared renderer (search-test dropdown markup) — single source of truth.
        window.SiteSearch.renderSearchTestDropdown(box, state.lastResults, function (r) { _stOnPick(state, r, LANG); });
    }
    async function _stFetch(state, q, LANG, IS_AR) {
        q = String(q || '').trim();
        if (!q) { _stHide(state); return; }
        _stShowLoading(state, IS_AR);
        const data = await window.SiteSearch.fetchResults(q, LANG); // shared fetch (never throws)
        _stRenderResults(state, data.results, data.status, LANG, IS_AR);
    }
    function _stDoSearch(suggestionsId, targetRoute, q) {
        const state = _stStateFor(suggestionsId, targetRoute);
        const LANG = _stPickLang();
        const IS_AR = (LANG === 'ar');
        clearTimeout(state.debounce);
        state.debounce = setTimeout(() => _stFetch(state, q, LANG, IS_AR), 150);
    }
    function _stOnEnter(suggestionsId, targetRoute) {
        const state = _stStateFor(suggestionsId, targetRoute);
        if (state.lastResults && state.lastResults[0]) {
            _stOnPick(state, state.lastResults[0], _stPickLang());
        }
    }

    function _stWireAll() {
        // COUNTRY-PRAYER-PAGE-SEARCH-PIPELINE-PARITY-FIX-1: the core lives in
        // js/site-search.js (loaded before app.js in index.html). If it is
        // somehow absent, no-op gracefully rather than throwing on every keystroke.
        if (!window.SiteSearch) { try { console.warn('[search] SiteSearch module not loaded — search disabled'); } catch (_) {} return; }
        // 1) #loc-hero-search → homepage `/` AND /prayer-times-in-{city}.
        //    Inline HTML handlers `oninput="onHeroSearchInput(this.value)"`
        //    + `onkeydown="onHeroSearchKeyDown(event)"` resolve to the
        //    `window.onHeroSearchInput` property at call time. Reassigning
        //    redirects to our pipeline for ANY page that has #loc-hero-search.
        const heroInput = document.getElementById('loc-hero-search');
        if (heroInput) {
            window.onHeroSearchInput = function (q) {
                _stDoSearch('loc-hero-suggestions', 'prayer-times', q);
            };
            window.onHeroSearchKeyDown = function (e) {
                if (!e) return;
                if (e.key === 'Enter') {
                    e.preventDefault();
                    _stOnEnter('loc-hero-suggestions', 'prayer-times');
                } else if (e.key === 'Escape') {
                    _stHide(_stStateFor('loc-hero-suggestions', 'prayer-times'));
                    try { heroInput.blur(); } catch (_) {}
                }
            };
        }

        // 2) #moon-hub-search → /moon-today, /moon-today-in-{city}.
        // 3) #qibla-hub-search → /qibla.
        //    Both are wired by their respective legacy `_wireMoonHubHero` /
        //    qibla hero functions via:
        //       searchEl.addEventListener('input',   () => onCitySearchInput(value, CTX));
        //       searchEl.addEventListener('keydown', e  => onSearchKeyDown(e, CTX));
        //    where CTX.targetRoute = 'moon-hub' or 'qibla-hub'. We override
        //    `window.onCitySearchInput` + `window.onSearchKeyDown` to route
        //    those ctx values to our pipeline. Other ctx values (default
        //    `_DEFAULT_SEARCH_CTX` from elsewhere) fall back to the original.
        const _origOnCitySearchInput = window.onCitySearchInput;
        const _origOnSearchKeyDown   = window.onSearchKeyDown;
        window.onCitySearchInput = function (q, ctx) {
            if (ctx && (ctx.targetRoute === 'moon-hub' || ctx.targetRoute === 'qibla-hub')) {
                const suggestionsId = ctx.suggestionsId ||
                    (ctx.targetRoute === 'moon-hub' ? 'moon-hub-suggestions' : 'qibla-hub-suggestions');
                _stDoSearch(suggestionsId, ctx.targetRoute, q);
                return;
            }
            if (typeof _origOnCitySearchInput === 'function') {
                return _origOnCitySearchInput.apply(this, arguments);
            }
        };
        window.onSearchKeyDown = function (e, ctx) {
            if (ctx && (ctx.targetRoute === 'moon-hub' || ctx.targetRoute === 'qibla-hub')) {
                const suggestionsId = ctx.suggestionsId ||
                    (ctx.targetRoute === 'moon-hub' ? 'moon-hub-suggestions' : 'qibla-hub-suggestions');
                if (!e) return;
                if (e.key === 'Enter') {
                    e.preventDefault();
                    _stOnEnter(suggestionsId, ctx.targetRoute);
                } else if (e.key === 'Escape') {
                    _stHide(_stStateFor(suggestionsId, ctx.targetRoute));
                    const inputEl = document.getElementById(ctx.inputId || (suggestionsId.replace('-suggestions', '-search')));
                    if (inputEl) try { inputEl.blur(); } catch (_) {}
                }
                return;
            }
            if (typeof _origOnSearchKeyDown === 'function') {
                return _origOnSearchKeyDown.apply(this, arguments);
            }
        };

        try { console.log('[search-test-pipeline] active · lang=' + _stPickLang()); } catch (_) {}
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _stWireAll, { once: true });
    } else {
        _stWireAll();
    }
})();
